/* imported header fragment CSS: HEADER_MENU (2dc1b800-000a-4217-9d3d-1a75dd21cd62) */
/* ─── Тематические настройки ─── */
:root[data-theme="dark"] {
  --res-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
  --res-item-hover: rgba(255, 255, 255, 0.05);
  --res-icon-bg: rgba(255, 255, 255, 0.03);
  --res-desc: rgba(255, 255, 255, 0.5);
}

:root[data-theme="light"] {
  --res-shadow: 0 15px 30px rgba(0, 0, 0, 0.08);
  --res-item-hover: rgba(0, 0, 0, 0.03);
  --res-icon-bg: rgba(0, 0, 0, 0.02);
  --res-desc: var(--color-gray-second);
}

.header-menu {
  margin-left: auto;
  margin-right: 30px;
}

.header-menu-list {
  display: flex;
  column-gap: 3.9375rem;
}

.header-menu-item {
  position: relative;
}

/* Свечение при ховере */
.header-menu-item::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  height: 100%;
  background-image: var(--menu-item-bg, none);
  background-repeat: no-repeat;
  background-position: center bottom;
  background-size: contain;
  opacity: 0;
  transition: opacity var(--transition-duration)
    cubic-bezier(0.34, 1.56, 0.64, 1);
  pointer-events: none;
  z-index: 1;
}

.header-menu-item:hover::after {
  opacity: 1;
}

.header-menu-link,
.resources-trigger {
  display: inline-flex;
  align-items: center;
  padding-inline: 0.625rem;
  height: var(--header-height);
  font-size: 1.25rem;
  color: var(--color-heading);
  transition: color var(--transition-duration) ease;
}

.resources-dropdown-wrapper {
  display: flex;
  align-items: center;
}

.resources-trigger {
  background: none;
  border: none;
  font-family: inherit;
  cursor: pointer;
  gap: 8px;
}

.resources-chevron {
  transition: transform 0.25s ease;
}

.resources-dropdown-wrapper.is-open .resources-chevron {
  transform: rotate(180deg);
}

.resources-menu-dropdown {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  min-width: 580px;
  background-color: var(--locale-selector-bg);
  border-radius: 1.25rem;
  padding: 1.5rem;
  box-shadow: var(--res-shadow);
  border: 1px solid var(--card-border);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 1000;
}

.resources-menu-dropdown::before {
  content: "";
  position: absolute;
  top: -20px;
  left: 0;
  right: 0;
  height: 25px;
}

.resources-dropdown-wrapper.is-open .resources-menu-dropdown {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}

.resources-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.resource-item {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 0.875rem;
  border-radius: 0.75rem;
  text-decoration: none;
  transition: background-color 0.2s ease;
}

.resource-item:hover {
  background-color: var(--res-item-hover);
}

.resource-icon {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--res-icon-bg);
  border: 1px solid var(--card-border);
  border-radius: 10px;
  color: #6bc0f9;
}

.resource-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.resource-title {
  color: var(--color-heading);
  font-size: 1rem;
  font-weight: 500;
}

.resource-desc {
  color: var(--res-desc);
  font-size: 0.8125rem;
  line-height: 1.4;
}

/* ─── Industries Mega-Menu ─── */
.ind-mega-menu {
  min-width: 960px;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  padding: 0;
  overflow: hidden;
  display: flex;
}

.resources-dropdown-wrapper.is-open .ind-mega-menu {
  transform: translateX(-50%) translateY(0);
}

.ind-left {
  flex-shrink: 0;
  width: 268px;
  padding: 1rem 0.5rem;
  border-right: 1px solid var(--card-border);
}

.ind-nav-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ind-nav-item {
  list-style: none;
}

.ind-nav-btn {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  width: 100%;
  padding: 0.625rem 0.75rem;
  border: none;
  background: none;
  border-radius: 0.625rem;
  cursor: pointer;
  color: var(--color-heading);
  font-size: 0.9375rem;
  font-weight: 400;
  text-align: left;
  transition:
    background-color 0.18s ease,
    color 0.18s ease;
}

.ind-nav-btn:hover,
.ind-nav-item.is-active .ind-nav-btn {
  background-color: rgba(90, 79, 207, 0.07);
  color: #5a4fcf;
}

:root[data-theme="dark"] .ind-nav-btn:hover,
:root[data-theme="dark"] .ind-nav-item.is-active .ind-nav-btn {
  background-color: rgba(107, 79, 207, 0.15);
  color: #9b8df5;
}

.ind-nav-icon {
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: inherit;
  opacity: 0.7;
}

.ind-nav-item.is-active .ind-nav-icon,
.ind-nav-btn:hover .ind-nav-icon {
  opacity: 1;
}

.ind-nav-label {
  flex: 1;
  line-height: 1.3;
}

.ind-nav-chevron {
  flex-shrink: 0;
  opacity: 0;
  transition: opacity 0.18s ease;
  color: inherit;
}

.ind-nav-btn:hover .ind-nav-chevron,
.ind-nav-item.is-active .ind-nav-chevron {
  opacity: 1;
}

/* Right panel */
.ind-right {
  flex: 1;
  position: relative;
  min-height: 420px;
}

.ind-panel {
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
}

.ind-panel.is-active {
  opacity: 1;
  pointer-events: auto;
}

/* Default panel */
.ind-panel--default {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 2.5rem;
  text-align: center;
  gap: 0.5rem;
}

.ind-default-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: rgba(90, 79, 207, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.5rem;
}

:root[data-theme="dark"] .ind-default-icon {
  background: rgba(107, 79, 207, 0.2);
}

.ind-default-title {
  font-size: 1.375rem;
  font-weight: 700;
  color: var(--color-heading);
  margin: 0 0 0.25rem;
}

.ind-default-desc {
  font-size: 0.9375rem;
  color: var(--res-desc);
  max-width: 280px;
}

.ind-default-sub {
  font-size: 0.875rem;
  color: var(--res-desc);
  max-width: 280px;
  margin-top: 0.25rem;
}

/* Industry content panel */
.ind-panel--industry {
  display: flex;
  align-items: flex-start;
  gap: 0;
  padding: 1.75rem 1.5rem 1.75rem 1.75rem;
}

.ind-industry-desc {
  flex: 0 0 300px;
  padding-right: 1.5rem;
  border-right: 1px solid var(--card-border);
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  align-self: stretch;
