.ind-industry-label {
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #5a4fcf;
}

:root[data-theme="dark"] .ind-industry-label {
  color: #9b8df5;
}

.ind-industry-title {
  font-size: 1.375rem;
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-heading);
  margin: 0;
}

.ind-industry-body {
  font-size: 0.875rem;
  color: var(--res-desc);
  line-height: 1.5;
  flex: 1;
