.ind-cta-link {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: #5a4fcf;
  text-decoration: none;
  margin-top: 0.5rem;
  transition:
    gap 0.2s ease,
    opacity 0.2s ease;
