:root[data-theme="dark"] .ind-cta-link {
  color: #9b8df5;
}

.ind-cta-link:hover {
  gap: 0.5rem;
  opacity: 0.8;
}

.ind-cta-link.is-disabled {
  opacity: 0.45;
  pointer-events: none;
}

.ind-cta-link--outline {
