  border-radius: 100px;
  padding: 0.5rem 1.25rem;
  margin-top: 0.75rem;
  color: #5a4fcf;
}

:root[data-theme="dark"] .ind-cta-link--outline {
  border-color: #9b8df5;
  color: #9b8df5;
