}

.ind-sub-item:has(.ind-badge) {
  pointer-events: none;
  opacity: 0.5;
}

.ind-sub-icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #5a4fcf;
}

:root[data-theme="dark"] .ind-sub-icon {
  color: #9b8df5;
}

.ind-sub-item span:not(.ind-sub-icon):not(.ind-badge) {
  flex: 1;
}

.ind-sub-arrow {
  flex-shrink: 0;
  color: var(--color-gray);
  opacity: 0;
  transition: opacity 0.18s ease;
}

.ind-sub-item:hover .ind-sub-arrow {
  opacity: 1;
}

.ind-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 7px;
  border-radius: 100px;
  font-family:
    "Vela Sans",
    Manrope,
    Inter,
    system-ui,
    -apple-system,
    sans-serif;
  font-size: 0.6875rem;
  font-weight: 600;
  line-height: 1.35;
  background: rgba(79, 149, 255, 0.09);
  color: #4f95ff;
  margin-left: 0.375rem;
}

:root[data-theme="dark"] .ind-badge {
  background: rgba(79, 149, 255, 0.14);
  color: #7db0ff;
}

/* Media Queries */
@media (max-width: 120rem) {
  .header-menu-list {
