  }
}

@media (width < 80rem) {
  .header-menu {
    display: none;
  }
}

.vl-locale-selector {
  position: relative;
  display: inline-block;
  z-index: 100;
  isolation: isolate;
}

.vl-locale-trigger {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.375rem;
  padding-inline: 0.9375rem;
  height: 2.625rem;
  border: none;
  border-radius: var(--radius-xs);
  /* background-color: var(--color-nav-blur-bg); */
  background: linear-gradient(
    188.96deg,
    var(--sw-surface-2) 15.85%,
    var(--color-breadcrumb-fade) 92.84%
  );
  cursor: pointer;
  white-space: nowrap;
  position: relative;
  min-width: 11.25rem;
  transition: border-radius var(--dur-fast) ease;
}

.vl-locale-trigger-left {
  display: flex;
  align-items: center;
  gap: 0.375rem;
}

.vl-locale-selector.is-open .vl-locale-trigger {
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

.vl-locale-selector.is-open .vl-locale-chevron {
  transform: rotate(180deg);
}

.vl-locale-chevron {
  flex-shrink: 0;
  transition: transform var(--dur-slow) var(--ease-snap);
}

.vl-locale-dropdown {
  position: absolute;
  top: 100%;
  /* left: 0; */
  /* min-width: 100%; */
  background-color: var(--color-bg);
  border-bottom-right-radius: var(--radius-md);
  border-bottom-left-radius: var(--radius-md);
  box-shadow: var(--shadow-press);
  overflow: hidden;
  z-index: 9999;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(0.625rem);
  transition:
    opacity var(--dur-normal) var(--ease-snap),
    transform var(--dur-normal) var(--ease-snap),
    visibility var(--dur-normal);
}

.vl-locale-dropdown::before {
  content: "";
  position: absolute;
  top: -1.25rem;
  left: 0;
  right: 0;
  height: 1.5625rem;
  background: transparent;
}

.vl-locale-selector.is-open .vl-locale-dropdown {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0);
}

.vl-locale-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.125rem;
  max-height: 19rem;
  overflow-y: auto;
}

.vl-locale-item {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.625rem 0.875rem;
  cursor: pointer;
  white-space: nowrap;
  position: relative;
  opacity: 0;
  transform: translateX(-0.25rem);
  transition:
    opacity var(--dur-fast) ease,
    transform var(--dur-fast) ease,
    background-color var(--dur-normal) ease;
}

.vl-locale-selector.is-open .vl-locale-item {
  opacity: 1;
  transform: translateX(0);
}

/* stagger animation */
.vl-locale-selector.is-open .vl-locale-item:nth-child(1) {
  transition-delay: 40ms;
}
.vl-locale-selector.is-open .vl-locale-item:nth-child(2) {
  transition-delay: 70ms;
}
.vl-locale-selector.is-open .vl-locale-item:nth-child(3) {
  transition-delay: 100ms;
}
.vl-locale-selector.is-open .vl-locale-item:nth-child(4) {
  transition-delay: 130ms;
}
.vl-locale-selector.is-open .vl-locale-item:nth-child(5) {
  transition-delay: 160ms;
}
.vl-locale-selector.is-open .vl-locale-item:nth-child(6) {
  transition-delay: 190ms;
}

.vl-locale-item:hover {
  background-color: var(--color-locale-item-hover);
}

.vl-locale-item.is-active {
  background-color: var(--color-locale-item-active);
}

.vl-locale-item-label {
  font-size: var(--fs-16);
  flex: 1;
}

.vl-locale-check {
  width: 0.875rem;
  height: 0.875rem;
  flex-shrink: 0;
  color: var(--sw-sky-soft);
  opacity: 0;
  transform: scale(0.6);
  transition:
    opacity var(--dur-fast) ease,
    transform var(--dur-fast) var(--ease-snap);
}

.vl-locale-item.is-active .vl-locale-check {
  opacity: 1;
  transform: scale(1);
}

.vl-locale-flag {
  width: 1.25rem !important;
  height: 0.75rem !important;
  flex-shrink: 0;
}

@media (width < 80rem) {
  .vl-locale-selector {
    display: none;
  }
}

